-- 478: Original BrillaPrep Cambridge A-Level Biology (9700) Membranes and Transport questions (batch alevel-bio-sprint2-001).
-- Curriculum-aligned practice content; not official Cambridge International or WAEC material.
PRAGMA foreign_keys = ON;
CREATE TABLE _migration_478_expected (id TEXT PRIMARY KEY, topic_id TEXT, subject_id TEXT, exam_type_id TEXT, paper_type_id TEXT, past_paper_id TEXT, question_text TEXT, question_type TEXT, round_type TEXT, options TEXT, correct_answer TEXT, explanation TEXT, difficulty TEXT, points INTEGER, marks INTEGER, time_limit INTEGER, question_number INTEGER, section TEXT, is_compulsory INTEGER, image_url TEXT, syllabus_topic_id TEXT, command_word TEXT, assessment_objective TEXT, source_paper_code TEXT, source_question_number TEXT, exam_board_id TEXT);
INSERT INTO _migration_478_expected (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_albio_membranes_s2_001', 'topic_alevel_bio_membranes', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'Which property of phospholipid molecules causes them to form a bilayer in water?', 'multiple_choice', NULL, '["A. They are fully hydrophilic, so they dissolve in the cell sap","B. They are polymers built from glucose monomers","C. They contain peptide bonds that cross-link the two layers","D. They are amphipathic, with a hydrophilic phosphate head and hydrophobic fatty acid tails"]', 'D', 'Phospholipids have a polar, hydrophilic phosphate head and non-polar, hydrophobic fatty acid tails. In water the heads face the aqueous solutions on each side while the tails avoid water and point inwards, so a bilayer forms spontaneously. Phospholipids are lipids, not glucose polymers, and contain no peptide bonds; a fully hydrophilic molecule would dissolve rather than form a membrane. Therefore the correct answer is D: They are amphipathic, with a hydrophilic phosphate head and hydrophobic fatty acid tails.', 'easy', '2', '1', '60', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_cambridge'),
('q_albio_membranes_s2_002', 'topic_alevel_bio_membranes', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'Which statement correctly defines osmosis?', 'multiple_choice', NULL, '["A. The net movement of water molecules across a partially permeable membrane from a region of higher (less negative) water potential to a region of lower (more negative) water potential","B. The movement of solute molecules from a dilute solution to a concentrated solution","C. The active transport of water molecules against their water potential gradient","D. The diffusion of water from a region of lower water potential to a region of higher water potential"]', 'A', 'Osmosis concerns water, not solute: water moves by diffusion across a partially permeable membrane down its own water potential gradient — from higher (less negative) to lower (more negative) water potential. No ATP is involved, so osmosis cannot be active transport, and water cannot diffuse up its own potential gradient. Therefore the correct answer is A: The net movement of water molecules across a partially permeable membrane from a region of higher (less negative) water potential to a region of lower (more negative) water potential.', 'easy', '2', '1', '60', NULL, NULL, '1', NULL, NULL, 'State', 'AO1', NULL, NULL, 'board_cambridge'),
('q_albio_membranes_s2_003', 'topic_alevel_bio_membranes', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'Which change would increase the rate of simple diffusion of oxygen across a cell surface membrane?', 'multiple_choice', NULL, '["A. Decreasing the temperature of the cell","B. Increasing the concentration gradient of oxygen across the membrane","C. Increasing the thickness of the membrane","D. Decreasing the surface area of the membrane"]', 'B', 'Fick’s law states that the rate of diffusion is proportional to (surface area × concentration gradient) ÷ thickness of the exchange surface. A steeper concentration gradient therefore speeds diffusion, while a thicker membrane, a smaller surface area or a lower temperature (which slows molecular motion) all reduce the rate. Oxygen is small and non-polar, so it dissolves through the phospholipid bilayer and needs no carrier protein. Therefore the correct answer is B: Increasing the concentration gradient of oxygen across the membrane.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Apply', 'AO2', NULL, NULL, 'board_cambridge'),
('q_albio_membranes_s2_004', 'topic_alevel_bio_membranes', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'Which statement correctly describes the role of cholesterol in the cell surface membrane?', 'multiple_choice', NULL, '["A. It forms channels that allow ions to cross the membrane by facilitated diffusion","B. It acts as an energy store that is respired when ATP runs low","C. It sits between the phospholipids and regulates fluidity, restraining phospholipid movement to give the membrane mechanical stability","D. It acts as the main receptor molecule for hormone recognition"]', 'C', 'Cholesterol is a small lipid that inserts between the phospholipid tails, with its hydroxyl group held near the heads. It buffers fluidity: at higher temperatures it restrains phospholipid movement, and at lower temperatures it stops the tails packing too closely, while also reducing permeability to small water-soluble molecules. Transport channels are proteins, energy storage is not a membrane role of cholesterol, and hormone receptors are glycoproteins or glycolipids. Therefore the correct answer is C: It sits between the phospholipids and regulates fluidity, restraining phospholipid movement to give the membrane mechanical stability.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Describe', 'AO1', NULL, NULL, 'board_cambridge'),
('q_albio_membranes_s2_005', 'topic_alevel_bio_membranes', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'Glucose is absorbed from the small intestine into epithelial cells even when its concentration in the gut lumen is lower than inside the cells. Which mechanism makes this possible?', 'multiple_choice', NULL, '["A. Simple diffusion of glucose through the phospholipid bilayer","B. Facilitated diffusion of glucose down its own concentration gradient","C. Exocytosis of glucose-containing vesicles into the epithelial cells","D. Cotransport, in which sodium ions move down their electrochemical gradient through a carrier protein that simultaneously carries glucose in against its gradient"]', 'D', 'This is secondary active transport: the sodium–potassium pump keeps the sodium concentration low inside the epithelial cell, so sodium ions flow back in down their gradient through a cotransporter protein, dragging glucose with them even against the glucose gradient. Glucose is polar and cannot cross the bilayer by simple diffusion; facilitated diffusion can only move glucose down, not against, its gradient; and exocytosis exports material from cells in vesicles — it does not absorb glucose. Therefore the correct answer is D: Cotransport, in which sodium ions move down their electrochemical gradient through a carrier protein that simultaneously carries glucose in against its gradient.', 'hard', '4', '1', '120', NULL, NULL, '1', NULL, NULL, 'Explain', 'AO2', NULL, NULL, 'board_cambridge');
CREATE TABLE _migration_478_expected_parts (id TEXT PRIMARY KEY, question_id TEXT NOT NULL, part_label TEXT NOT NULL, part_text TEXT NOT NULL, marks INTEGER NOT NULL, correct_answer TEXT NOT NULL, display_order INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS _migration_478_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_478_guard;
INSERT INTO _migration_478_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM _migration_478_expected e JOIN questions q ON q.id = e.id WHERE NOT (q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id)) AND NOT EXISTS (SELECT 1 FROM _migration_478_expected e JOIN question_content_releases r ON r.question_id = e.id WHERE NOT (r.batch_id IS 'alevel-bio-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge International AS & A Level Biology (9700) syllabus; not official Cambridge International or WAEC examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-international-as-and-a-level-biology-9700/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) SELECT id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id FROM _migration_478_expected e WHERE NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = e.id);
INSERT INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT e.id, 'alevel-bio-sprint2-001', 'automated_beta', 'beta', 'Original BrillaPrep practice content aligned to the published Cambridge International AS & A Level Biology (9700) syllabus; not official Cambridge International or WAEC examination material. Use the enabled feedback channel to report corrections.', 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-international-as-and-a-level-biology-9700/', 0, 1 FROM _migration_478_expected e WHERE NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = e.id);
DELETE FROM _migration_478_guard;
INSERT INTO _migration_478_guard(valid) SELECT CASE WHEN (SELECT COUNT(*) FROM questions q JOIN _migration_478_expected e ON e.id = q.id AND q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id) = 5 AND (SELECT COUNT(*) FROM question_content_releases r JOIN _migration_478_expected e ON e.id = r.question_id WHERE r.batch_id IS 'alevel-bio-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge International AS & A Level Biology (9700) syllabus; not official Cambridge International or WAEC examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-international-as-and-a-level-biology-9700/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1) = 5 AND (SELECT COUNT(*) FROM questions q JOIN topics t ON t.id = q.topic_id AND t.subject_id = q.subject_id JOIN _migration_478_expected e ON e.id = q.id) = 5 AND (SELECT COUNT(*) FROM structured_question_parts sp JOIN _migration_478_expected_parts p ON p.id = sp.id AND sp.id IS p.id AND sp.question_id IS p.question_id AND sp.part_label IS p.part_label AND sp.part_text IS p.part_text AND sp.marks IS p.marks AND sp.correct_answer IS p.correct_answer AND sp.display_order IS p.display_order) = 0 THEN 1 ELSE 0 END;
DROP TABLE _migration_478_guard;
